mapper.delete:
/* 양수 게시글 삭제하기 */
DELETE
FROM
	assignee_board
WHERE
	assignee_no = #{assigneeBoardNum};

mapper.update:
  		/* 양도 게시글 수정 */
  		UPDATE assignee_board
		
			
				rental_fee = #{rentalFee}, 
			
			
				remaining_months = #{remainingMonths},
			
			
				desired_install_area= #{desiredInstallArea}, 
			
			
				quantity = #{quantity} ,
				
			
				assignee_content = #{assigneeContent}	
				
		
		WHERE
			assignee_no = #{assigneeBoardNum};

mapper.insert:
  		/* 등록 */
  		INSERT INTO assignee_board
		(assignee_no, cust_id, product_category_no, products_nm, rental_fee, remaining_months, desired_install_area, quantity, assignee_content, board_valid_date, register_date, revision_date)
		VALUES(#{assigneeBoardNum}, #{customerId}, #{productCategoryNum}, #{productName}, #{rentalFee}, #{remainingMonths}, #{desiredInstallArea}, 1, #{assigneeContent}, DATE_ADD(NOW(), INTERVAL 1 MONTH), NOW(), NOW());

mapper.select:
/* 양수 게시글 목록 조회 */ SELECT ab.assignee_no, ab.cust_id, c.cust_nm , ab.product_category_no, pc.middle_category , pc.small_category , ab.products_nm, ab.rental_fee, ab.remaining_months, ab.desired_install_area, ab.quantity, ab.assignee_content, ab.board_valid_date, ab.register_date, ab.revision_date FROM customer c RIGHT JOIN assignee_board ab USING (cust_id) INNER JOIN products_category pc USING (product_category_no)
DATEDIFF(ab.board_valid_date, NOW()) >= 0
AND ab.products_nm LIKE CONCAT('%', #{searchValue}, '%')
ORDER BY
DATEDIFF(ab.board_valid_date, NOW()) ASC,
ab.register_date DESC LIMIT #{pageable.rowPerPage} OFFSET #{pageable.offset};
